import{_ as t,o,c as a,a5 as s}from"./chunks/framework.BjM_ivYE.js";const u=JSON.parse('{"title":"Developer Setup Guide","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/level-0/developers-guide.md","filePath":"guides/level-0/developers-guide.md","lastUpdated":1790671199000}'),i={name:"guides/level-0/developers-guide.md"};function n(r,e,l,d,h,p){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="developer-setup-guide" tabindex="-1">Developer Setup Guide <a class="header-anchor" href="#developer-setup-guide" aria-label="Permalink to &quot;Developer Setup Guide&quot;">​</a></h1><p><strong>Goal:</strong> Clone the RBQ repository, set up the development environment, and launch the simulator so you can test robot behavior before running on hardware.</p><div class="sb sb-required"><div class="sb-icon"><span class="sb-book" aria-hidden="true">📖</span></div><div class="sb-content"><p class="custom-block-title">REQUIRED READING</p><p>Familiarize yourself with the safety guidelines before testing on the real robot: <a href="/RBQ/manual/safety/general-safety-warning-precautions">General Safety Guidelines</a>.</p></div></div><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Requirement</th></tr></thead><tbody><tr><td>OS</td><td>Ubuntu 22.04 (x86-64)</td></tr><tr><td>CPU</td><td>Intel Core i7 12th Gen or equivalent</td></tr><tr><td>RAM</td><td>16 GB or more</td></tr><tr><td>Storage</td><td>25 GB free space</td></tr><tr><td>Control</td><td>Keyboard (W/A/S/D, Q/E, arrow keys) or Logitech F710 gamepad</td></tr></tbody></table><h2 id="step-1-clone-the-repository" tabindex="-1">Step 1. Clone the Repository <a class="header-anchor" href="#step-1-clone-the-repository" aria-label="Permalink to &quot;Step 1. Clone the Repository&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span></code></pre></div><blockquote><p>All SDK source code, examples, scripts, and simulator environments live inside <code>RBQ/</code>.<br> Run all commands from this directory unless stated otherwise.</p></blockquote><blockquote><p><strong>Note:</strong> Pre-built binaries ship in <code>bin-x86_64/</code> (and <code>bin-aarch64/</code> for arm64). No compilation step is required to run the simulator or deploy to the robot.</p></blockquote><h2 id="step-2-launch-the-simulator" tabindex="-1">Step 2. Launch the Simulator <a class="header-anchor" href="#step-2-launch-the-simulator" aria-label="Permalink to &quot;Step 2. Launch the Simulator&quot;">​</a></h2><p>The simulator runs in Docker — Docker is the only thing to install, and the script offers to install it when it is missing. The first run takes a few minutes to build its image. See <a href="/RBQ/software/simulator/mujoco.html">MuJoCo</a>.</p><p>Start the RBQ control stack and the MuJoCo physics simulator together:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-gui</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # motion only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-gui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # motion + vision sensors</span></span></code></pre></div><p>It runs in the foreground of this terminal; Ctrl-C stops it. If Docker needs <code>sudo</code> on this PC, enter your password when asked.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>Pass <code>--no-gui</code>. This repository carries no on-PC control GUI — you drive the simulator from the <strong>RBQ</strong> app, exactly as you drive the real robot.</p></div></div><h2 id="step-3-connect-and-stand-the-robot-up-in-the-rbq-app" tabindex="-1">Step 3. Connect and stand the robot up in the RBQ app <a class="header-anchor" href="#step-3-connect-and-stand-the-robot-up-in-the-rbq-app" aria-label="Permalink to &quot;Step 3. Connect and stand the robot up in the RBQ app&quot;">​</a></h2><p>Install the RBQ desktop app from the <strong><a href="/RBQ/manual/downloads/">Downloads</a></strong> page, then:</p><ol><li>Start the app <strong>on the same PC</strong> as the simulator. With no robot network around, the desktop app finds the MuJoCo simulator on this PC by itself and connects — see <a href="/RBQ/manual/gui/connection.html">Connection</a>.</li><li>Press <strong>Control</strong> on the hub to open the control home.</li><li>Tap the green <strong>Auto Start</strong> pill, press <strong>Auto Start</strong> in the dialog, and wait for the sequence to report <strong>Done</strong>. Press <strong>Close</strong>.</li><li>Press <code>STAND</code> on the motion card to stand the robot up.</li></ol><p>The robot is now ready to receive commands. Refer to <a href="/RBQ/manual/gui/motion-commands.html">Motion commands</a> for joystick and gait control.</p><h2 id="step-4-run-on-the-real-robot" tabindex="-1">Step 4. Run on the Real Robot <a class="header-anchor" href="#step-4-run-on-the-real-robot" aria-label="Permalink to &quot;Step 4. Run on the Real Robot&quot;">​</a></h2><p>When you are ready to test on hardware:</p><ol><li>Place the robot in the <a href="/RBQ/guides/common/initial-pose.html">correct initial pose</a>.</li><li>Connect your device to the robot Wi-Fi (<code>RBQ_xxxx</code>).</li><li>Open the RBQ app and pick the robot in the robot list — see <a href="/RBQ/manual/gui/connection.html">Connection</a>.</li><li>Press <strong>Control</strong>, run <strong>Auto Start</strong>, then press <code>STAND</code>.</li></ol><p>The steps are the same ones you just used against the simulator, which is the point of rehearsing there first.</p><blockquote><p>It is strongly recommended to verify all behaviors in simulation before testing on the real robot.</p></blockquote><h2 id="step-5-update-the-robot" tabindex="-1">Step 5. Update the Robot <a class="header-anchor" href="#step-5-update-the-robot" aria-label="Permalink to &quot;Step 5. Update the Robot&quot;">​</a></h2><p>Robot software is updated from the app with <strong><code>Send robot software</code></strong> on the <code>Software update</code> screen. The robot deploys it as soon as the transfer completes, and the app then offers a reboot.</p><p><strong>→ <a href="/RBQ/manual/gui/software-update.html">Robot Software Update</a></strong></p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Put the robot in the <strong>sitting</strong> state before restarting, and do not move it until the restart finishes. Running a mismatched binary and script combination can cause unexpected behavior.</p></div></div><h2 id="detailed-reference" tabindex="-1">Detailed Reference <a class="header-anchor" href="#detailed-reference" aria-label="Permalink to &quot;Detailed Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Link</th></tr></thead><tbody><tr><td>Full walkthrough</td><td><a href="/RBQ/software/developers-guide.html">Developers Guide (Software)</a></td></tr><tr><td>The RBQ app, screen by screen</td><td><a href="/RBQ/manual/gui/introduction.html">RBQ App</a></td></tr><tr><td>Simulation environment</td><td><a href="/RBQ/software/developers-guide.html#simulation">MuJoCo Simulation</a></td></tr><tr><td>Concepts &amp; architecture</td><td><a href="/RBQ/software/concept.html">Concept</a></td></tr></tbody></table>`,30)])])}const b=t(i,[["render",n]]);export{u as __pageData,b as default};
